package dev.monocalendar.rp1;

import java.io.*;
import java.nio.charset.Charset;
import java.util.*;

/**
 * Offline calendar: assets/almanac.bin is generated by scripts/build-almanac.mjs from the same
 * 6tail lunar library the server used, so lunar dates, terms, ganzhi and yi/ji match it exactly.
 * Festival rules match ha-app/server/core.mjs.
 */
public final class Almanac {
    public static final int FIRST_YEAR = 1901, LAST_YEAR = 2099;
    private static final long FIRST_DAY = epochDay(1900, 12, 1);
    private static final int RECORD = 13;
    static final String STEMS = "甲乙丙丁戊己庚辛壬癸", BRANCHES = "子丑寅卯辰巳午未申酉戌亥";
    static final String[] TERMS = {"小寒", "大寒", "立春", "雨水", "惊蛰", "春分", "清明", "谷雨", "立夏", "小满",
        "芒种", "夏至", "小暑", "大暑", "立秋", "处暑", "白露", "秋分", "寒露", "霜降", "立冬", "小雪", "大雪", "冬至"};
    static final String JIANCHU = "建除满平定执破危成收开闭", ZODIAC = "鼠牛虎兔龙蛇马羊猴鸡狗猪", SHA = "东南西北";
    static final String[] MONTHS = {"", "正", "二", "三", "四", "五", "六", "七", "八", "九", "十", "冬", "腊"};
    static final String[] DAYS = {"", "初一", "初二", "初三", "初四", "初五", "初六", "初七", "初八", "初九", "初十",
        "十一", "十二", "十三", "十四", "十五", "十六", "十七", "十八", "十九", "二十", "廿一", "廿二", "廿三", "廿四",
        "廿五", "廿六", "廿七", "廿八", "廿九", "三十"};
    private static final Map<String, String> SOLAR = new HashMap<>(), LUNAR = new HashMap<>();
    static {
        String[] solar = {"1-1", "元旦", "2-14", "情人节", "3-8", "妇女节", "5-1", "劳动节", "5-4", "青年节", "6-1",
            "儿童节", "7-1", "建党节", "8-1", "建军节", "9-10", "教师节", "10-1", "国庆节", "10-31", "万圣夜", "11-1",
            "万圣节", "12-24", "平安夜", "12-25", "圣诞节"};
        for (int i = 0; i < solar.length; i += 2)
            SOLAR.put(solar[i], solar[i + 1]);
        String[] lunar = {"1-1", "春节", "1-15", "元宵节", "2-2", "龙抬头", "5-5", "端午节", "7-7", "七夕", "7-15",
            "中元节", "8-15", "中秋节", "9-9", "重阳节", "12-8", "腊八节", "12-23", "小年"};
        for (int i = 0; i < lunar.length; i += 2)
            LUNAR.put(lunar[i], lunar[i + 1]);
    }

    private final byte[] data;
    private final String[] lists;
    public Almanac(InputStream table, InputStream words) throws IOException {
        data = readAll(table);
        BufferedReader reader = new BufferedReader(new InputStreamReader(words, Charset.forName("UTF-8")));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null)
            lines.add(line);
        lists = lines.toArray(new String[0]);
    }
    private static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        byte[] buffer = new byte[65536];
        int bytesRead;
        while ((bytesRead = in.read(buffer)) > 0)
            output.write(buffer, 0, bytesRead);
        in.close();
        return output.toByteArray();
    }

    /** One civil day. */
    public static final class Day {
        public final int year, month, day;
        public final long epoch;
        public final boolean known;
        public final int lunarMonth, lunarDay, term, dayGz, monthGz, yearGz, jianchu, chong, sha;
        public final String yi, ji, label;
        public final boolean strong;
        public final List<String> names;
        Day(int year, int month, int day, long epoch, boolean known, int lunarMonth, int lunarDay, int term, int dayGz,
            int monthGz, int yearGz, int jianchu, int chong, int sha, String yi, String ji, String label,
            boolean strong, List<String> names) {
            this.year = year;
            this.month = month;
            this.day = day;
            this.epoch = epoch;
            this.known = known;
            this.lunarMonth = lunarMonth;
            this.lunarDay = lunarDay;
            this.term = term;
            this.dayGz = dayGz;
            this.monthGz = monthGz;
            this.yearGz = yearGz;
            this.jianchu = jianchu;
            this.chong = chong;
            this.sha = sha;
            this.yi = yi;
            this.ji = ji;
            this.label = label;
            this.strong = strong;
            this.names = names;
        }
        public int weekday() {
            return Almanac.weekday(epoch);
        } // 0 = Sunday
        public String iso() {
            return String.format(Locale.US, "%04d-%02d-%02d", year, month, day);
        }
        public String lunarText() {
            return (lunarMonth < 0 ? "闰" : "") + MONTHS[Math.abs(lunarMonth)] + "月" + DAYS[lunarDay];
        }
        public String ganzhi() {
            return gz(yearGz) + "年 " + gz(monthGz) + "月 " + gz(dayGz) + "日";
        }
        public String meta() {
            return JIANCHU.charAt(jianchu) + "日 冲" + ZODIAC.charAt(chong) + " 煞" + SHA.charAt(sha);
        }
        public int isoWeek() {
            long thursday = epoch - mod(epoch + 3, 7) + 3;
            int[] c = civil(thursday);
            return (int) ((thursday - epochDay(c[0], 1, 1)) / 7) + 1;
        }
    }
    static String gz(int i) {
        return "" + STEMS.charAt(i % 10) + BRANCHES.charAt(i % 12);
    }

    /** Bounded LRU of computed days (a named class: D8 rejects anonymous classes in field initialisers). */
    private static final class DayCache extends LinkedHashMap<Long, Day> {
        DayCache() {
            super(512, 0.75f, true);
        }
        @Override
        protected boolean removeEldestEntry(Map.Entry<Long, Day> e) {
            return size() > 1024;
        }
    }
    private final Map<Long, Day> cache = new DayCache();

    public Day day(int y, int m, int d) {
        return day(epochDay(y, m, d));
    }
    public synchronized Day day(long epoch) {
        Day cached = cache.get(epoch);
        if (cached != null)
            return cached;
        int[] civilDate = civil(epoch);
        long index = epoch - FIRST_DAY;
        Day result;
        if (civilDate[0] < FIRST_YEAR || civilDate[0] > LAST_YEAR || index < 0 || (index + 1) * RECORD > data.length)
            result = new Day(civilDate[0], civilDate[1], civilDate[2], epoch, false, 0, 0, -1, 0, 0, 0, 0, 0, 0, "", "",
                "", false, Collections.<String>emptyList());
        else {
            int recordOffset = (int) index * RECORD;
            int lunarMonth = data[recordOffset];
            int lunarDay = data[recordOffset + 1] & 255;
            int term = data[recordOffset + 2] & 255;
            String yi = lists[((data[recordOffset + 9] & 255) << 8) | (data[recordOffset + 10] & 255)];
            String ji = lists[((data[recordOffset + 11] & 255) << 8) | (data[recordOffset + 12] & 255)];
            List<String> names = new ArrayList<>();
            String label;
            if (lunarDay == 1) {
                String leapPrefix = lunarMonth < 0 ? "闰" : "";
                label = leapPrefix + MONTHS[Math.abs(lunarMonth)] + "月";
            } else {
                label = DAYS[lunarDay];
            }
            boolean strong = false;
            String lunarFestival = lunarMonth > 0 ? LUNAR.get(lunarMonth + "-" + lunarDay) : null;
            if (lunarFestival != null) {
                label = lunarFestival;
                strong = true;
                names.add(lunarFestival);
            }
            long nextIndex = index + 1;
            if (nextIndex * RECORD + 1 < data.length && data[(int) nextIndex * RECORD] == 1
                && data[(int) nextIndex * RECORD + 1] == 1) {
                label = "除夕";
                strong = true;
                names.add("除夕");
            }
            if (term != 255) {
                if (!strong)
                    label = TERMS[term];
                strong = true;
                names.add(TERMS[term]);
            }
            String solarFestival = SOLAR.get(civilDate[1] + "-" + civilDate[2]);
            int weekday = weekday(epoch);
            if (civilDate[1] == 11 && weekday == 4 && civilDate[2] >= 22 && civilDate[2] <= 28)
                solarFestival = "感恩节";
            if (civilDate[1] == 5 && weekday == 0 && civilDate[2] >= 8 && civilDate[2] <= 14)
                solarFestival = "母亲节";
            if (civilDate[1] == 6 && weekday == 0 && civilDate[2] >= 15 && civilDate[2] <= 21)
                solarFestival = "父亲节";
            if (solarFestival != null) {
                label = solarFestival;
                strong = true;
                names.add(0, solarFestival);
            }
            result = new Day(civilDate[0], civilDate[1], civilDate[2], epoch, true, lunarMonth, lunarDay,
                term == 255 ? -1 : term, data[recordOffset + 3] & 255, data[recordOffset + 4] & 255,
                data[recordOffset + 5] & 255, data[recordOffset + 6] & 255, data[recordOffset + 7] & 255,
                data[recordOffset + 8] & 255, yi, ji, label, strong, names);
        }
        cache.put(epoch, result);
        return result;
    }

    public static final class Upcoming {
        public final String name;
        public final Day day;
        public final int daysAhead;

        Upcoming(String name, Day day, int daysAhead) {
            this.name = name;
            this.day = day;
            this.daysAhead = daysAhead;
        }
    }

    /** The next terms and festivals after the given day, up to limit entries. */
    public List<Upcoming> upcoming(long from, int limit) {
        List<Upcoming> result = new ArrayList<>();
        for (int daysAhead = 1; daysAhead <= 400 && result.size() < limit; daysAhead++) {
            Day day = day(from + daysAhead);
            if (!day.known)
                break;
            for (String name : day.names)
                if (result.size() < limit)
                    result.add(new Upcoming(name, day, daysAhead));
        }
        return result;
    }

    static int weekday(long epoch) {
        return (int) mod(epoch + 4, 7);
    }

    static long mod(long a, long b) {
        long r = a % b;
        return r < 0 ? r + b : r;
    }
    static long div(long a, long b) {
        long q = a / b;
        return (a % b != 0 && ((a < 0) != (b < 0))) ? q - 1 : q;
    }
    // Proleptic Gregorian day numbers (days since 1970-01-01), after H. Hinnant's civil algorithms.
    public static long epochDay(int y, int m, int d) {
        y -= m <= 2 ? 1 : 0;
        long era = div(y, 400);
        long yoe = y - era * 400;
        long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe - 719468;
    }
    public static int[] civil(long z) {
        z += 719468;
        long era = div(z, 146097);
        long doe = z - era * 146097;
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        long mp = (5 * doy + 2) / 153;
        int d = (int) (doy - (153 * mp + 2) / 5 + 1), m = (int) (mp < 10 ? mp + 3 : mp - 9);
        return new int[] {(int) (y + (m <= 2 ? 1 : 0)), m, d};
    }
}
